def construct_distanced_sequence(n: int) -> List[int]:
    size = 2 * n - 1
    seq = [0] * size
    used = [False] * (n + 1)

    def fill(pos: int) -> bool:
        while pos < size and seq[pos]:
            pos += 1
        if pos == size:
            return True
        for v in range(n, 0, -1):
            if used[v]:
                continue
            far = pos + v if v > 1 else pos          # second copy for v > 1
            if far < size and seq[far] == 0:
                seq[pos] = seq[far] = v
                used[v] = True
                if fill(pos + 1):
                    return True
                seq[pos] = seq[far] = 0
                used[v] = False
        return False

    fill(0)
    return seq

def min_time_to_reach(moveTime: List[List[int]]) -> int:
    n, m = len(moveTime), len(moveTime[0])
    INF = float("inf")
    dist = [[INF] * m for _ in range(n)]
    dist[0][0] = 0
    heap = [(0, 0, 0)]
    while heap:
        t, i, j = heapq.heappop(heap)
        if t > dist[i][j]:
            continue
        if i == n - 1 and j == m - 1:
            return t
        step = 1 if (i + j) % 2 == 0 else 2     # parity of moves made so far
        for x, y in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
            if 0 <= x < n and 0 <= y < m:
                nt = max(t, moveTime[x][y]) + step
                if nt < dist[x][y]:
                    dist[x][y] = nt
                    heapq.heappush(heap, (nt, x, y))
    return dist[n - 1][m - 1]

def answer_string(word: str, numFriends: int) -> str:
