    left = 0
    zeros = 0                       # zeros inside the window
    for right, v in enumerate(nums):
        if v == 0:
            zeros += 1
        while zeros > 1:            # shrink until at most one zero remains
            if nums[left] == 0:
                zeros -= 1
            left += 1
        best = max(best, right - left + 1)
    return best

