def subtree_with_all_deepest(root: Optional[TreeNode]) -> Optional[TreeNode]:
    # Post order with an explicit stack: info[node] = (height, answer for that subtree)
    info = {None: (-1, None)}
    stack = [(root, False)]
    while stack:
        node, visited = stack.pop()
        if node is None:
            continue
        if not visited:
            stack.append((node, True))
            stack.append((node.left, False))
            stack.append((node.right, False))
            continue
        lh, lans = info[node.left]
        rh, rans = info[node.right]
        if lh > rh:
            info[node] = (lh + 1, lans)
        elif rh > lh:
            info[node] = (rh + 1, rans)
        else:
            info[node] = (lh + 1, node)
    return info[root][1]

