def min_size_subarray(nums: List[int], target: int) -> int:
    n = len(nums)
    cycle_sum = sum(nums)
    full_cycles, rem = divmod(target, cycle_sum)
    if rem == 0:
        return full_cycles * n

    # Shortest window with sum rem inside nums + nums (indices taken modulo n).
    best = float("inf")
    left = 0
    window = 0
    for right in range(2 * n):
        window += nums[right % n]
        while window > rem:
            window -= nums[left % n]
            left += 1
        if window == rem:
            best = min(best, right - left + 1)
    if best == float("inf"):
        return -1
    return full_cycles * n + best

def least_frequent_digit(n: int) -> int:
    counts = [0] * 10
    while n > 0:
        counts[n % 10] += 1
        n //= 10
    best_digit, best_count = -1, float("inf")
    # Scanning digits in increasing order and using a strict comparison keeps the
    # smallest digit on ties.
    for d in range(10):
        if 0 < counts[d] < best_count:
            best_digit, best_count = d, counts[d]
    return best_digit

def construct_2d_array(original: list[int], m: int, n: int) -> list[list[int]]:
    if len(original) != m * n:
        return []
    # Row r is the contiguous block original[r*n : (r+1)*n].
    return [original[r * n:(r + 1) * n] for r in range(m)]

