def longest_balanced(s: str) -> int:
    n = len(s)
    total_ones = s.count("1")
    total_zeros = n - total_ones
    # first and second index (in the prefix array 0..n) where each prefix value occurs;
    # prefix values are shifted by n so they can index a list
    first = [-1] * (2 * n + 3)
    second = [-1] * (2 * n + 3)
    first[n] = 0
    best = 0
    prefix = n
    for j in range(1, n + 1):
        prefix += 1 if s[j - 1] == "1" else -1
        # Without a swap: earliest index with the same prefix value.
        f = first[prefix]
        if f >= 0 and j - f > best:
            best = j - f
        # With a swap: substring sum +2 needs a zero outside it, sum -2 needs a one outside.
        for key, outside in ((prefix - 2, total_zeros), (prefix + 2, total_ones)):
            f = first[key]
            if f < 0:
                continue
            length = j - f
            inside = (length - 2) // 2            # minority characters inside the substring
            if outside - inside > 0:
                if length > best:
                    best = length
            else:
                # The earliest start swallows every outside character; the second
                # occurrence is shorter by a zero sum block and always leaves one free.
                sec = second[key]
                if sec >= 0 and j - sec > best:
                    best = j - sec
        if first[prefix] < 0:
            first[prefix] = j
        elif second[prefix] < 0:
            second[prefix] = j
    return best

