def longest_nice_substring(s: str) -> str:
    if len(s) < 2:
        return ""
    present = set(s)
    for i, ch in enumerate(s):
        if ch.swapcase() not in present:
            # ch can never be in a nice substring: solve both sides and keep the earliest longest.
            left = longest_nice_substring(s[:i])
            right = longest_nice_substring(s[i + 1:])
            return left if len(left) >= len(right) else right
    return s

def process_str(s: str) -> str:
    result = []
    for ch in s:
        if ch == "*":
            if result:
                result.pop()
        elif ch == "#":
            result.extend(result)       # append a copy of the whole result
        elif ch == "%":
            result.reverse()
        else:
            result.append(ch)
    return "".join(result)

def max_sum(nums: list[int]) -> int:
    positives = {x for x in nums if x > 0}
    if positives:
        return sum(positives)
    # Nothing positive: keep the single largest element.
    return max(nums)

def soup_servings(n: int) -> float:
    units = (n + 24) // 25            # round up to whole 25 ml servings
    if units >= 200:
        return 1.0                     # beyond this the answer is 1 within 1e-5

    @lru_cache(maxsize=None)
    def prob(a: int, b: int) -> float:
        if a <= 0 and b <= 0:
            return 0.5
        if a <= 0:
            return 1.0
        if b <= 0:
            return 0.0
        return 0.25 * (prob(a - 4, b) + prob(a - 3, b - 1)
                       + prob(a - 2, b - 2) + prob(a - 1, b - 3))

    return prob(units, units)

def two_edit_words(queries: list[str], dictionary: list[str]) -> list[str]:
    def within_two(a: str, b: str) -> bool:
        mismatches = 0
        for x, y in zip(a, b):
            if x != y:
                mismatches += 1
                if mismatches > 2:
                    return False
        return True

    return [q for q in queries if any(within_two(q, w) for w in dictionary)]

