def house_of_cards(n: int) -> int:
    ways = [0] * (n + 1)
    ways[0] = 1
    cost = 2                      # a row with k triangles costs 3k - 1 cards
    while cost <= n:
        # Each row size may be used at most once, so sweep totals downward.
        for total in range(n, cost - 1, -1):
            ways[total] += ways[total - cost]
        cost += 3
    return ways[n]

def min_flips(mat: list[list[int]]) -> int:
    m, n = len(mat), len(mat[0])
    start = 0
    for i in range(m):
        for j in range(n):
            if mat[i][j]:
                start |= 1 << (i * n + j)
    # flip[c] is the bit pattern toggled by pressing cell c.
    flips = []
    for i in range(m):
        for j in range(n):
            mask = 1 << (i * n + j)
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                r, c = i + di, j + dj
                if 0 <= r < m and 0 <= c < n:
                    mask |= 1 << (r * n + c)
            flips.append(mask)
    dist = {start: 0}
    queue = deque([start])
    while queue:
        state = queue.popleft()
        if state == 0:
            return dist[state]
        for f in flips:
            nxt = state ^ f
            if nxt not in dist:
                dist[nxt] = dist[state] + 1
                queue.append(nxt)
    return -1

def min_patches(nums: list[int], n: int) -> int:
    patches = 0
    miss = 1          # smallest value not yet representable
    i = 0
    while miss <= n:
        if i < len(nums) and nums[i] <= miss:
            miss += nums[i]      # the element extends the covered range
            i += 1
        else:
            miss += miss         # patch `miss` itself, doubling the range
            patches += 1
    return patches

def circular_array_loop(nums: list[int]) -> bool:
    n = len(nums)
    arr = nums[:]                      # working copy; 0 marks a dead index

    def step(i: int) -> int:
        return (i + arr[i]) % n

    for start in range(n):
        if arr[start] == 0:
            continue
        forward = arr[start] > 0
        slow = fast = start
        while True:
            # Advance slow by one and fast by two, only across same sign moves.
            nxt = step(slow)
            if arr[nxt] == 0 or (arr[nxt] > 0) != forward:
                break
            slow = nxt
            nxt = step(fast)
            if arr[nxt] == 0 or (arr[nxt] > 0) != forward:
                break
            fast = nxt
            nxt = step(fast)
            if arr[nxt] == 0 or (arr[nxt] > 0) != forward:
                break
            fast = nxt
            if slow == fast:
                if step(slow) == slow:
                    break              # one element loop does not count
                return True
        # The path from start (in its direction) cannot be part of a cycle.
        i = start
        while arr[i] != 0 and (arr[i] > 0) == forward:
            nxt = step(i)
            arr[i] = 0
            i = nxt
    return False

