def num_components(head: Optional[ListNode], nums: list[int]) -> int:
    marked = set(nums)
    components = 0
    in_run = False                # whether the previous node was marked
    node = head
    while node:
        if node.val in marked:
            if not in_run:
                components += 1   # a new run starts here
            in_run = True
        else:
            in_run = False
        node = node.next
    return components

def shortest_path_length(graph: list[list[int]]) -> int:
    n = len(graph)
    full = (1 << n) - 1
    if n == 1:
        return 0
    # Multi source BFS over (visited mask, current node).
    queue = deque((1 << i, i, 0) for i in range(n))
    seen = [False] * ((1 << n) * n)
    for i in range(n):
        seen[(1 << i) * n + i] = True
    while queue:
        mask, node, dist = queue.popleft()
        for nxt in graph[node]:
            nmask = mask | (1 << nxt)
            if nmask == full:
                return dist + 1
            key = nmask * n + nxt
            if not seen[key]:
                seen[key] = True
                queue.append((nmask, nxt, dist + 1))
    return -1   # unreachable for a connected graph

def reorder_log_files(logs: list[str]) -> list[str]:
    def key(line: str):
        identifier, content = line.split(" ", 1)
        if content[0].isdigit():
            return (1,)                         # digit logs: keep input order
        return (0, content, identifier)         # letter logs: by content, then id
    return sorted(logs, key=key)                # Python's sort is stable

def k_weakest_rows(mat: list[list[int]], k: int) -> list[int]:
    def soldiers(row: list[int]) -> int:
        # First index holding a 0, found by binary search on the sorted row.
        lo, hi = 0, len(row)
        while lo < hi:
            mid = (lo + hi) // 2
            if row[mid] == 1:
                lo = mid + 1
            else:
                hi = mid
        return lo

    heap = [(soldiers(row), i) for i, row in enumerate(mat)]
    heapq.heapify(heap)
    return [heapq.heappop(heap)[1] for _ in range(k)]

def check_contradictions(equations: list[list[str]], values: list[float]) -> bool:
    parent = {}
    weight = {}          # weight[x] = value(x) / value(parent[x])

    def find(x: str) -> str:
        if x not in parent:
            parent[x] = x
            weight[x] = 1.0
            return x
        # Iterative path compression, multiplying weights along the way.
        path = []
        while parent[x] != x:
            path.append(x)
            x = parent[x]
        root = x
        acc = 1.0
        for node in reversed(path):
            acc *= weight[node]
            weight[node] = acc
            parent[node] = root
        return root

    for (a, b), v in zip(equations, values):
        ra, rb = find(a), find(b)
        if ra == rb:
            # Both relative to the same root: check consistency.
            if abs(weight[a] / weight[b] - v) >= 1e-5:
                return True
        else:
            parent[ra] = rb
            weight[ra] = v * weight[b] / weight[a]
    return False

def maximum_cost_substring(s: str, chars: str, vals: list[int]) -> int:
    value = {chr(ord("a") + i): i + 1 for i in range(26)}   # default alphabet positions
    for ch, v in zip(chars, vals):
        value[ch] = v
    best = 0            # the empty substring is always available
    current = 0         # best sum of a substring ending here
    for ch in s:
        current = max(0, current + value[ch])
        if current > best:
            best = current
    return best

def sort_jumbled(mapping: list[int], nums: list[int]) -> list[int]:
    table = str.maketrans("0123456789", "".join(str(d) for d in mapping))

    def mapped(x: int) -> int:
        # int() drops any leading zeros the mapping may have produced.
        return int(str(x).translate(table))

    return sorted(nums, key=mapped)     # stable: equal mapped values keep input order
